import{_ as t,c as n,o as s,ai as a,j as i}from"./chunks/framework.BrjRfu4a.js";const g=JSON.parse('{"title":"Time Series Analysis | Financial Engineering Basics | Financial Engineering","description":"Time series analysis is a methodology for analyzing temporal patterns in financial data and forecasting future movements, serving as a core tool in financial engineering. This page explores various aspects of time series analysis, including characteristics of time series data, stationarity concepts, major time series models (ARIMA, GARCH), volatility modeling, deep learning-based forecasting methods, and applications to real financial market prediction.","frontmatter":{"title":"Time Series Analysis | Financial Engineering Basics | Financial Engineering","description":"Time series analysis is a methodology for analyzing temporal patterns in financial data and forecasting future movements, serving as a core tool in financial engineering. This page explores various aspects of time series analysis, including characteristics of time series data, stationarity concepts, major time series models (ARIMA, GARCH), volatility modeling, deep learning-based forecasting methods, and applications to real financial market prediction.","head":[["meta",{"property":"og:title","content":"Time Series Analysis | Financial Engineering Basics | Financial Engineering"}],["meta",{"property":"og:description","content":"Time series analysis is a methodology for analyzing temporal patterns in financial data and forecasting future movements, serving as a core tool in financial engineering. This page explores various aspects of time series analysis, including characteristics of time series data, stationarity concepts, major time series models (ARIMA, GARCH), volatility modeling, deep learning-based forecasting methods, and applications to real financial market prediction."}],["meta",{"property":"og:image","content":"/images/Financial-Engineering.png"}],["meta",{"property":"og:url","content":"https://risk-quant-haun.github.io/financial-engineering/basics/time-series"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://risk-quant-haun.github.io/ko/financial-engineering/basics/time-series"}],["link",{"rel":"alternate","hreflang":"en","href":"https://risk-quant-haun.github.io/financial-engineering/basics/time-series"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://risk-quant-haun.github.io/ko/financial-engineering/basics/time-series"}],["link",{"rel":"canonical","href":"https://risk-quant-haun.github.io/financial-engineering/basics/time-series"}]],"date":"2025-02-17T00:00:00.000Z"},"headers":[],"relativePath":"financial-engineering/basics/time-series.md","filePath":"en/financial-engineering/basics/time-series.md"}'),l={name:"financial-engineering/basics/time-series.md"};function o(r,e,c,d,p,u){return s(),n("div",null,e[0]||(e[0]=[a('<h1 id="time-series-analysis" tabindex="-1">Time Series Analysis <a class="header-anchor" href="#time-series-analysis" aria-label="Permalink to &quot;Time Series Analysis&quot;">​</a></h1><p><strong>Financial Engineering Basics | 2025.02.17</strong></p><p><strong>Time Series Analysis is a statistical methodology for analyzing and modeling data observed sequentially over time, serving as an essential tool for understanding the dynamic characteristics of financial markets and forecasting future movements.</strong></p><p><strong>Most data generated in financial markets takes the form of time series, and understanding temporal patterns and structures in stock prices, interest rates, exchange rates, volatility, etc., plays an important role in various areas of financial engineering, including investment decision-making, risk management, and derivative pricing.</strong></p><p><strong>This page will explore various methodologies of financial time series analysis, from the characteristics of time series data and stationarity concepts to linear and nonlinear time series models, volatility modeling, multivariate time series analysis, and state-of-the-art machine learning-based approaches, and learn how to apply them to real financial problems.</strong></p><h2 id="_1️⃣-basic-concepts-and-characteristics-of-time-series-data" tabindex="-1">1️⃣ Basic Concepts and Characteristics of Time Series Data <a class="header-anchor" href="#_1️⃣-basic-concepts-and-characteristics-of-time-series-data" aria-label="Permalink to &quot;1️⃣ Basic Concepts and Characteristics of Time Series Data&quot;">​</a></h2><p>Time series data is a <code>set of observations recorded sequentially at regular time intervals</code>. Unlike other forms of data, time series data has the characteristic that <code>temporal order has significant meaning</code> and there exists temporal dependence among observations.</p><h3 id="types-of-financial-time-series-data" tabindex="-1">Types of Financial Time Series Data <a class="header-anchor" href="#types-of-financial-time-series-data" aria-label="Permalink to &quot;Types of Financial Time Series Data&quot;">​</a></h3>',8),i("div",{class:"tip custom-block"},[i("p",{class:"custom-block-title"},"Main Financial Time Series Data"),i("ul",null,[i("li",null,[i("p",null,[i("strong",null,"Price Time Series")]),i("ul",null,[i("li",null,"Price changes over time for stocks, bonds, commodities, exchange rates, etc."),i("li",null,"Generally provided as daily, weekly, monthly, or minute/second-level data"),i("li",null,"Raw price data usually exhibits non-stationary characteristics")])]),i("li",null,[i("p",null,[i("strong",null,"Return Time Series")]),i("ul",null,[i("li",null,"Time series representing the rate of price change, calculated in two ways:"),i("li",{"t-1":""},"Simple Return: (P_t - P_{t-1}) / P_"),i("li",null,"Log Return: ln(P_t / P_{t-1})"),i("li",null,"Return data exhibits characteristics closer to stationarity than prices")])]),i("li",null,[i("p",null,[i("strong",null,"Volume Time Series")]),i("ul",null,[i("li",null,"Trading volume or transaction amount for securities, futures, options, etc."),i("li",null,"Useful for evaluating market activity and liquidity"),i("li",null,"Seasonality such as intraday patterns and day-of-week effects are frequently observed")])]),i("li",null,[i("p",null,[i("strong",null,"Volatility Time Series")]),i("ul",null,[i("li",null,"Indicators representing the magnitude of return fluctuations"),i("li",null,"Realized Volatility, Implied Volatility, etc."),i("li",null,"Volatility clustering phenomenon is frequently observed")])]),i("li",null,[i("p",null,[i("strong",null,"Spread Time Series")]),i("ul",null,[i("li",null,"Price differences between two different financial instruments"),i("li",null,"Credit spreads, yield curve spreads, basis spreads, etc."),i("li",null,"Often exhibits mean-reversion characteristics")])])])],-1),a(`<h3 id="main-characteristics-of-financial-time-series" tabindex="-1">Main Characteristics of Financial Time Series <a class="header-anchor" href="#main-characteristics-of-financial-time-series" aria-label="Permalink to &quot;Main Characteristics of Financial Time Series&quot;">​</a></h3><p>Financial time series data has several important characteristics that distinguish it from other time series. Understanding these characteristics is essential for effective modeling and analysis.</p><div class="warning custom-block"><p class="custom-block-title">Characteristics of Financial Time Series</p><ul><li><p><strong>Non-stationarity</strong></p><ul><li>Financial price time series generally exhibit non-stationary characteristics with mean and variance changing over time</li><li>Often have a unit root and possess a stochastic trend</li><li>Processes such as differencing or transformation are needed to approach stationarity</li></ul></li><li><p><strong>Volatility Clustering</strong></p><ul><li>Tendency for large changes to follow large changes and small changes to follow small changes</li><li>Periods of high and low volatility appear in clusters</li><li>Can be modeled with ARCH/GARCH family models</li></ul></li><li><p><strong>Fat-Tailed Distribution</strong></p><ul><li>Financial returns exhibit fat-tailed distributions where extreme events occur more frequently than normal distribution</li><li>Kurtosis is greater than 3 (normal distribution value)</li><li>Modeled with t-distribution, GED (Generalized Error Distribution), etc.</li></ul></li><li><p><strong>Autocorrelation</strong></p><ul><li>Characteristic where current observations are correlated with past observations</li><li>Financial returns often show low levels of autocorrelation</li><li>Volatility tends to show high autocorrelation</li></ul></li><li><p><strong>Leverage Effect</strong></p><ul><li>Phenomenon where price declines have a stronger correlation with volatility increases</li><li>Effect of increasing leverage as corporate debt ratios rise during stock price declines</li><li>Modeled with asymmetric GARCH models (EGARCH, GJR-GARCH, etc.)</li></ul></li><li><p><strong>Seasonality and Cyclicality</strong></p><ul><li>Intraday, daily, weekly, monthly patterns</li><li>Regular variations according to specific times, days of week, months, etc.</li><li>Long-term cyclicality following business cycles</li></ul></li></ul></div><h3 id="stationarity-concept" tabindex="-1">Stationarity Concept <a class="header-anchor" href="#stationarity-concept" aria-label="Permalink to &quot;Stationarity Concept&quot;">​</a></h3><p>Stationarity is one of the most fundamental and important concepts in time series analysis. A stationary time series <code>maintains constant statistical characteristics regardless of time</code>.</p><div class="danger custom-block"><p class="custom-block-title">Stationarity of Time Series</p><ul><li><p><strong>Weak Stationarity</strong> A time series has weak stationarity when it satisfies the following conditions:</p><ol><li>Mean is constant over time: E[Y_t] = μ (constant)</li><li>Variance is constant over time: Var(Y_t) = σ² (constant)</li><li>Covariance between two time points depends only on time difference: Cov(Y_t, Y_{t+h}) = γ(h)</li></ol></li><li><p><strong>Strict Stationarity</strong> When the joint probability distribution of all dimensions is invariant to time shifts. That is, the joint distributions of (Y_t, Y_{t+1}, ..., Y_{t+k}) and (Y_{t+h}, Y_{t+h+1}, ..., Y_{t+h+k}) are identical for all t, h, k.</p></li><li><p><strong>Importance of Stationarity</strong></p><ul><li>Many time series models are developed under stationarity assumptions</li><li>General approach is to stationarize non-stationary time series for modeling</li><li>Incorrect stationarity assumptions can lead to problems like spurious regression</li></ul></li><li><p><strong>Stationarity Tests</strong></p><ul><li>Visual inspection: Check stability of mean and variance over time</li><li>ACF (Autocorrelation Function) analysis: Rapid decay indicates stationarity</li><li>Unit root tests: ADF (Augmented Dickey-Fuller), KPSS (Kwiatkowski-Phillips-Schmidt-Shin), PP (Phillips-Perron) tests, etc.</li></ul></li></ul></div><h3 id="components-of-time-series-data" tabindex="-1">Components of Time Series Data <a class="header-anchor" href="#components-of-time-series-data" aria-label="Permalink to &quot;Components of Time Series Data&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Main Components of Time Series</p><ul><li><p><strong>Trend Component</strong></p><ul><li>Long-term persistent upward or downward patterns</li><li>Can appear in various forms such as linear, quadratic, exponential</li><li>Can be analyzed through detrending</li></ul></li><li><p><strong>Seasonal Component</strong></p><ul><li>Patterns that repeat at regular intervals</li><li>Time (intraday, daily), day of week, monthly, quarterly, yearly, etc.</li><li>Can be removed through seasonal adjustment</li></ul></li><li><p><strong>Cyclical Component</strong></p><ul><li>Variations that occur in cycles longer than seasonality</li><li>Business cycle-related variations are typical</li><li>Often difficult to identify as cycles are not constant</li></ul></li><li><p><strong>Irregular Component</strong></p><ul><li>Random variations not explained by trend, seasonal, or cyclical components</li><li>Has characteristics close to white noise</li><li>Treated as error term in modeling</li></ul></li></ul></div><p>Understanding these basic concepts and characteristics of time series data is the first step in selecting appropriate analysis methods and models. In the next section, we will explore basic time series analysis techniques based on this understanding.</p><h2 id="_2️⃣-basic-time-series-analysis-methods" tabindex="-1">2️⃣ Basic Time Series Analysis Methods <a class="header-anchor" href="#_2️⃣-basic-time-series-analysis-methods" aria-label="Permalink to &quot;2️⃣ Basic Time Series Analysis Methods&quot;">​</a></h2><p>Basic tools and techniques for analyzing financial time series data play an important role in understanding data characteristics and determining appropriate modeling directions. This section will explore from preprocessing of time series data to basic analysis methods.</p><h3 id="time-series-data-visualization-and-preprocessing" tabindex="-1">Time Series Data Visualization and Preprocessing <a class="header-anchor" href="#time-series-data-visualization-and-preprocessing" aria-label="Permalink to &quot;Time Series Data Visualization and Preprocessing&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Time Series Data Exploration and Preprocessing</p><ul><li><p><strong>Time Series Plot</strong></p><ul><li>Visually confirm data changes over time</li><li>Identify trends, seasonality, structural changes, outliers, etc.</li><li>Identify interrelationships through simultaneous plotting of multiple time series</li></ul></li><li><p><strong>Transformation</strong></p><ul><li>Log transformation: Linearize exponential growth and reduce heteroskedasticity</li><li>Square root transformation: For moderate heteroskedasticity cases</li><li>Box-Cox transformation: Automatic selection of optimal power transformation for data</li></ul></li><li><p><strong>Differencing</strong></p><ul><li>First differencing: Y_t - Y_{t-1} (trend removal)</li><li>Seasonal differencing: Y_t - Y_{t-s} (s is seasonal period)</li><li>Log differencing: ln(Y_t) - ln(Y_{t-1}) = ln(Y_t/Y_{t-1}) (relative rate of change)</li></ul></li><li><p><strong>Normalization and Standardization</strong></p><ul><li>Min-Max normalization: (Y_t - min(Y)) / (max(Y) - min(Y))</li><li>Z-score standardization: (Y_t - mean(Y)) / std(Y)</li><li>Moving standardization: Standardization using moving average and moving standard deviation</li></ul></li><li><p><strong>Outlier Treatment</strong></p><ul><li>Outlier detection: Z-score, IQR method, moving average-based methods</li><li>Outlier removal or replacement: Interpolation, mean/median replacement, predicted value replacement</li></ul></li></ul></div><h3 id="time-series-decomposition" tabindex="-1">Time Series Decomposition <a class="header-anchor" href="#time-series-decomposition" aria-label="Permalink to &quot;Time Series Decomposition&quot;">​</a></h3><p>Time series decomposition is a technique that separates time series data into several components to individually analyze the characteristics and effects of each component.</p><div class="warning custom-block"><p class="custom-block-title">Time Series Decomposition Methods</p><ul><li><p><strong>Additive Model</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Y_t = Trend_t + Seasonal_t + Cyclical_t + Irregular_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>Suitable when the magnitude of variation in time series does not change significantly over time</li><li>Used when the effect of each component is relatively constant</li></ul></li><li><p><strong>Multiplicative Model</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Y_t = Trend_t × Seasonal_t × Cyclical_t × Irregular_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>Suitable when the magnitude of variation in time series changes over time</li><li>Used when seasonal effects expand over time</li><li>Can be converted to additive model through log transformation: log(Y_t) = log(Trend_t) + log(Seasonal_t) + ...</li></ul></li><li><p><strong>Main Decomposition Techniques</strong></p><ol><li><p><strong>Moving Average Decomposition</strong></p><ul><li>Extract trend-cycle component through moving average</li><li>Identify seasonal and irregular components by difference between original series and trend-cycle component</li></ul></li><li><p><strong>X-12-ARIMA/X-13-ARIMA-SEATS</strong></p><ul><li>Advanced seasonal adjustment method developed by U.S. Census Bureau</li><li>Complex decomposition method combining ARIMA modeling and moving averages</li><li>Can handle various factors such as outliers and calendar effects</li></ul></li><li><p><strong>STL (Seasonal and Trend decomposition using Loess)</strong></p><ul><li>Decomposition method using locally weighted regression (Loess)</li><li>Flexible in handling nonlinear trends and seasonality</li><li>Robust characteristics against outliers</li></ul></li><li><p><strong>TBATS (Trigonometric seasonality, Box-Cox transformation, ARMA errors, Trend and Seasonal components)</strong></p><ul><li>Method that can handle complex seasonality (multiple periods, non-integer periods, etc.)</li><li>Seasonality modeling using trigonometric functions</li><li>High ease of use with automated parameter selection</li></ul></li></ol></li></ul></div><h3 id="autocorrelation-analysis" tabindex="-1">Autocorrelation Analysis <a class="header-anchor" href="#autocorrelation-analysis" aria-label="Permalink to &quot;Autocorrelation Analysis&quot;">​</a></h3><p>Autocorrelation analysis is a basic tool for understanding the temporal dependence structure of time series data and is importantly used in model identification and diagnostics.</p><div class="danger custom-block"><p class="custom-block-title">Autocorrelation Analysis Tools</p><ul><li><p><strong>Autocorrelation Function (ACF)</strong></p><ul><li>Autocorrelation coefficient for lag k:<div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ρ(k) = Corr(Y_t, Y_{t-k})</span></span>
<span class="line"><span>     = Cov(Y_t, Y_{t-k}) / (σ_{Y_t} × σ_{Y_{t-k}})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li>Measures all linear dependencies (direct and indirect)</li><li>For stationary time series, converges to 0 as lag increases</li><li>For non-stationary time series, shows slowly decaying pattern</li></ul></li><li><p><strong>Partial Autocorrelation Function (PACF)</strong></p><ul><li>Pure autocorrelation of lag k with intermediate lag effects removed<div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>φ(k) = Corr(Y_t, Y_{t-k} | Y_{t-1}, Y_{t-2}, ..., Y_{t-k+1})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li>Measures only direct dependence after controlling for intermediate lag effects</li><li>Useful for identifying the order of AR models</li></ul></li><li><p><strong>Cross-Correlation Function (CCF)</strong></p><ul><li>Correlation between two time series X_t and Y_t for lag k<div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ρ_{XY}(k) = Corr(X_t, Y_{t-k})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li>Can identify whether one time series leads or lags another</li><li>Helps estimate direction of causality (basis for Granger causality test)</li></ul></li><li><p><strong>Autocorrelation Tests</strong></p><ul><li>Ljung-Box Q test: Test significance of autocorrelations over multiple lags</li><li>Box-Pierce test: Simplified version of Ljung-Box</li><li>Durbin-Watson test: First-order autocorrelation test (mainly used in residual analysis)</li></ul></li></ul></div><h3 id="statistical-hypothesis-testing" tabindex="-1">Statistical Hypothesis Testing <a class="header-anchor" href="#statistical-hypothesis-testing" aria-label="Permalink to &quot;Statistical Hypothesis Testing&quot;">​</a></h3><p>Various statistical hypothesis tests in financial time series analysis are important for characterizing data and determining appropriate modeling directions.</p><div class="info custom-block"><p class="custom-block-title">Main Time Series Hypothesis Tests</p><ul><li><p><strong>Unit Root Tests</strong></p><ul><li><p><strong>ADF (Augmented Dickey-Fuller) Test</strong>:</p><ul><li>H0: Time series has a unit root (non-stationary)</li><li>H1: Time series does not have a unit root (stationary)</li><li>Reject null hypothesis if test statistic is less than critical value (supports stationarity)</li></ul></li><li><p><strong>KPSS (Kwiatkowski-Phillips-Schmidt-Shin) Test</strong>:</p><ul><li>H0: Time series is trend stationary or stationary</li><li>H1: Time series has a unit root (non-stationary)</li><li>Opposite null hypothesis to ADF → Recommended to use together for confirmation</li></ul></li><li><p><strong>PP (Phillips-Perron) Test</strong>:</p><ul><li>Similar to ADF test but more robust to heteroskedasticity</li><li>Handles autocorrelation in error terms using non-parametric method</li></ul></li></ul></li><li><p><strong>Normality Tests</strong></p><ul><li><p><strong>Jarque-Bera Test</strong>:</p><ul><li>H0: Time series follows normal distribution</li><li>Test using skewness and kurtosis</li><li>Useful for identifying fat-tail characteristics of financial returns</li></ul></li><li><p><strong>Shapiro-Wilk Test</strong>, <strong>Kolmogorov-Smirnov Test</strong>:</p><ul><li>Various normality testing methods</li><li>Test power differs according to sample size</li></ul></li></ul></li><li><p><strong>Heteroskedasticity Tests</strong></p><ul><li><p><strong>ARCH LM (Lagrange Multiplier) Test</strong>:</p><ul><li>H0: No ARCH effect (homoskedasticity)</li><li>H1: ARCH effect exists (heteroskedasticity)</li><li>Useful for confirming volatility clustering</li></ul></li><li><p><strong>White Test</strong>, <strong>Breusch-Pagan Test</strong>:</p><ul><li>Heteroskedasticity test for regression models</li><li>Detect conditional heteroskedasticity structure</li></ul></li></ul></li><li><p><strong>Cointegration Tests</strong></p><ul><li><p><strong>Engle-Granger Test</strong>:</p><ul><li>Test for cointegration relationship between two time series</li><li>Residual-based approach</li></ul></li><li><p><strong>Johansen Test</strong>:</p><ul><li>Test for cointegration relationship in multivariate time series</li><li>Can determine number of cointegrating vectors</li><li>Based on maximum likelihood method</li></ul></li></ul></li></ul></div><p>These basic time series analysis methods provide an important foundation for understanding data characteristics and setting appropriate modeling directions. In the next section, we will explore linear time series models based on this understanding.</p><h2 id="_3️⃣-linear-time-series-models" tabindex="-1">3️⃣ Linear Time Series Models <a class="header-anchor" href="#_3️⃣-linear-time-series-models" aria-label="Permalink to &quot;3️⃣ Linear Time Series Models&quot;">​</a></h2><p>Linear time series models are important models that form the foundation of financial time series analysis, modeling the dynamic characteristics of time series through linear combinations of observed values. This section will explore major linear time series models and their applications.</p><h3 id="autoregressive-ar-model" tabindex="-1">Autoregressive (AR) Model <a class="header-anchor" href="#autoregressive-ar-model" aria-label="Permalink to &quot;Autoregressive (AR) Model&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Autoregressive (AR) Model</p><ul><li><p><strong>Definition</strong> The AR(p) model is a model where the current observation is expressed as a linear combination of past p observations:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Y_t = c + φ₁Y_{t-1} + φ₂Y_{t-2} + ... + φ_pY_{t-p} + ε_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where c is the constant term, φ₁, φ₂, ..., φ_p are AR coefficients, ε_t is white noise error term.</p></li><li><p><strong>Characteristics</strong></p><ul><li>Stationarity condition: All roots of AR polynomial must exist outside unit circle</li><li>Theoretical ACF: Gradually decaying pattern (exponential decay or sine wave form)</li><li>Theoretical PACF: Significant up to lag p and cut-off pattern thereafter</li><li>Has mean reversion characteristic: gradually reverts to mean after shock</li></ul></li><li><p><strong>Estimation Methods</strong></p><ul><li>Least Squares</li><li>Maximum Likelihood</li><li>Yule-Walker equations</li></ul></li><li><p><strong>Model Identification</strong></p><ul><li>Check PACF cut-off pattern: cuts off at lag p</li><li>Select optimal order through information criteria (AIC, BIC, HQIC, etc.)</li><li>Estimate models with various orders and compare performance</li></ul></li></ul></div><h3 id="moving-average-ma-model" tabindex="-1">Moving Average (MA) Model <a class="header-anchor" href="#moving-average-ma-model" aria-label="Permalink to &quot;Moving Average (MA) Model&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Moving Average (MA) Model</p><ul><li><p><strong>Definition</strong> The MA(q) model is a model where the current observation is expressed as a linear combination of current and past q error terms:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Y_t = μ + ε_t + θ₁ε_{t-1} + θ₂ε_{t-2} + ... + θ_qε_{t-q}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where μ is the mean, θ₁, θ₂, ..., θ_q are MA coefficients, ε_t is white noise error term.</p></li><li><p><strong>Characteristics</strong></p><ul><li>Always satisfies stationarity condition</li><li>Invertibility condition: All roots of MA polynomial must exist outside unit circle</li><li>Theoretical ACF: Significant up to lag q and cut-off pattern thereafter</li><li>Theoretical PACF: Gradually decaying pattern</li><li>Autocorrelation is exactly 0 after lag q</li></ul></li><li><p><strong>Estimation Methods</strong></p><ul><li>Maximum Likelihood</li><li>Nonlinear least squares</li><li>Conditional least squares</li></ul></li><li><p><strong>Model Identification</strong></p><ul><li>Check ACF cut-off pattern: cuts off at lag q</li><li>Select optimal order through information criteria</li><li>Check model invertibility</li></ul></li></ul></div><h3 id="autoregressive-integrated-moving-average-arima-model" tabindex="-1">Autoregressive Integrated Moving Average (ARIMA) Model <a class="header-anchor" href="#autoregressive-integrated-moving-average-arima-model" aria-label="Permalink to &quot;Autoregressive Integrated Moving Average (ARIMA) Model&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">ARIMA Model</p><ul><li><p><strong>Definition</strong> The ARIMA(p,d,q) model combines AR(p) and MA(q) models and stationarizes non-stationary time series through d-th order differencing:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(1-φ₁B-φ₂B²-...-φ_pBᵖ)(1-B)ᵈY_t = c + (1+θ₁B+θ₂B²+...+θ_qBᵍ)ε_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where B is the backshift operator (BY_t = Y_{t-1}).</p></li><li><p><strong>Components</strong></p><ul><li>AR(p): Autoregressive component, linear combination of past p observations</li><li>I(d): Integration (differencing) component, d-th order differencing for stationarity</li><li>MA(q): Moving average component, linear combination of past q error terms</li></ul></li><li><p><strong>Box-Jenkins Methodology</strong> Iterative approach to ARIMA model identification, estimation, and diagnostics:</p><ol><li><strong>Identification</strong>: Determine p, d, q values through ACF, PACF pattern analysis</li><li><strong>Estimation</strong>: Estimate model parameters</li><li><strong>Diagnostic checking</strong>: Verify model adequacy through residual analysis</li><li><strong>Forecasting</strong>: Predict future values using fitted model</li></ol></li><li><p><strong>Extended Models</strong></p><ul><li><p><strong>SARIMA</strong>: Seasonal ARIMA, includes seasonal patterns</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ARIMA(p,d,q)(P,D,Q)_s</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where (P,D,Q) is seasonal order, s is seasonal period</p></li><li><p><strong>ARIMAX</strong>: ARIMA with exogenous variables</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Y_t = ARIMA + β₁X₁_t + β₂X₂_t + ... + β_kX_k_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where X₁_t, X₂_t, ..., X_k_t are exogenous variables</p></li></ul></li></ul></div><h3 id="seasonal-adjustment-and-seasonal-models" tabindex="-1">Seasonal Adjustment and Seasonal Models <a class="header-anchor" href="#seasonal-adjustment-and-seasonal-models" aria-label="Permalink to &quot;Seasonal Adjustment and Seasonal Models&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Seasonality Handling Methods</p><ul><li><p><strong>Seasonal Differencing</strong> Differencing by subtracting a lag equal to the seasonal period from the original series:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>∇_s Y_t = Y_t - Y_{t-s}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where s is the seasonal period (e.g., 12 for monthly data)</p></li><li><p><strong>SARIMA (Seasonal ARIMA) Model</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(1-φ₁B-...-φ_pBᵖ)(1-Φ₁B^s-...-Φ_PB^{Ps})(1-B)^d(1-B^s)^D Y_t =</span></span>
<span class="line"><span>(1+θ₁B+...+θ_qB^q)(1+Θ₁B^s+...+Θ_QB^{Qs})ε_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li>(p,d,q): Non-seasonal ARIMA order</li><li>(P,D,Q): Seasonal ARIMA order</li><li>s: Seasonal period</li></ul></li><li><p><strong>Seasonal Decomposition Approach</strong></p><ul><li>X-13-ARIMA-SEATS: Advanced seasonal adjustment method</li><li>STL decomposition: Seasonal-trend decomposition using Loess</li><li>TBATS: Handles complex seasonality (multiple periods, changing seasonality, etc.)</li></ul></li><li><p><strong>Seasonality Modeling Using Fourier Series</strong> Model seasonality of various periods using trigonometric functions:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S_t = ∑[a_j sin(2πjt/s) + b_j cos(2πjt/s)]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where j is the number of harmonic components considered</p></li></ul></div><h3 id="vector-autoregression-var-model" tabindex="-1">Vector Autoregression (VAR) Model <a class="header-anchor" href="#vector-autoregression-var-model" aria-label="Permalink to &quot;Vector Autoregression (VAR) Model&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Multivariate Time Series Models</p><ul><li><p><strong>VAR Model Definition</strong> Generalized AR model that models interdependencies of multivariate time series:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Y_t = c + A₁Y_{t-1} + A₂Y_{t-2} + ... + A_pY_{t-p} + ε_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where Y_t is a k×1 vector, A_i is a k×k coefficient matrix, ε_t is white noise error term vector</p></li><li><p><strong>Characteristics of VAR Model</strong></p><ul><li>Models dynamic relationships among multivariate time series</li><li>Each variable is influenced by past values of itself and all other variables</li><li>Captures interactions and feedback effects among variables</li><li>Structural interpretation can be difficult</li></ul></li><li><p><strong>VAR Model Estimation</strong></p><ul><li>OLS (Ordinary Least Squares) estimation for each equation</li><li>Maximum Likelihood</li><li>Bayesian methodology (Bayesian VAR)</li></ul></li><li><p><strong>VAR-based Analysis Tools</strong></p><ul><li><strong>Impulse Response Function</strong>: Tracks the impact of a shock in one variable on other variables in the system over time</li><li><strong>Variance Decomposition</strong>: Decomposes forecast error variance of each variable into various structural shocks</li><li><strong>Granger Causality Test</strong>: Evaluates whether one variable provides useful information for predicting another variable</li></ul></li></ul></div><h3 id="error-correction-model-ecm" tabindex="-1">Error Correction Model (ECM) <a class="header-anchor" href="#error-correction-model-ecm" aria-label="Permalink to &quot;Error Correction Model (ECM)&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Cointegration and Error Correction Model</p><ul><li><p><strong>Cointegration Concept</strong> Characteristic where two or more non-stationary time series can form a stationary time series through linear combination:</p><ul><li>Each time series is I(1) but linear combination is I(0)</li><li>Represents long-run equilibrium relationship</li><li>Important meaning in financial markets: arbitrage opportunities, pair trading, etc.</li></ul></li><li><p><strong>Error Correction Model (ECM) Definition</strong> Models short-run and long-run dynamic relationships of variables with cointegration relationship:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ΔY_t = α + βΔX_t + γ(Y_{t-1} - θX_{t-1}) + ε_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where (Y_{t-1} - θX_{t-1}) is the error correction term representing deviation from long-run equilibrium</p></li><li><p><strong>Characteristics of ECM</strong></p><ul><li>Captures both short-run dynamics (ΔY_t, ΔX_t) and long-run equilibrium (error correction term)</li><li>γ is the adjustment coefficient representing the speed of return to equilibrium when deviating from equilibrium</li><li>Granger Representation Theorem: If cointegration relationship exists, can be represented as ECM</li></ul></li><li><p><strong>Vector Error Correction Model (VECM)</strong> Multivariate extended version of VAR model with error correction term added:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ΔY_t = α + Γ₁ΔY_{t-1} + ... + Γ_{p-1}ΔY_{t-p+1} + ΠY_{t-1} + ε_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where Π is the long-run relationship matrix, decomposable as Π = αβ&#39; (α: adjustment coefficient, β: cointegrating vector)</p></li></ul></div><p>Linear time series models provide the foundation for financial time series analysis, but have <code>limitations in sufficiently capturing many characteristics of financial data (volatility clustering, asymmetry, fat tails, etc.)</code>. In the next section, we will explore volatility models and nonlinear time series models to overcome these limitations.</p><h2 id="_4️⃣-volatility-models" tabindex="-1">4️⃣ Volatility Models <a class="header-anchor" href="#_4️⃣-volatility-models" aria-label="Permalink to &quot;4️⃣ Volatility Models&quot;">​</a></h2><p>One of the important characteristics of financial time series is the <code>volatility clustering phenomenon</code>, which refers to the tendency that &quot;large changes are followed by large changes, and small changes are followed by small changes.&quot; Volatility models that consider conditional heteroskedasticity have been developed to model these characteristics.</p><h3 id="arch-autoregressive-conditional-heteroskedasticity-model" tabindex="-1">ARCH (Autoregressive Conditional Heteroskedasticity) Model <a class="header-anchor" href="#arch-autoregressive-conditional-heteroskedasticity-model" aria-label="Permalink to &quot;ARCH (Autoregressive Conditional Heteroskedasticity) Model&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">ARCH Model Basics</p><ul><li><p><strong>Concept of ARCH Model</strong> A model where the variance of the error term depends on the square of past error terms, proposed by Robert Engle in 1982.</p></li><li><p><strong>ARCH(q) Model Definition</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>r_t = μ_t + ε_t</span></span>
<span class="line"><span>ε_t = σ_t z_t, z_t ~ N(0,1)</span></span>
<span class="line"><span>σ_t² = ω + α₁ε_{t-1}² + α₂ε_{t-2}² + ... + α_qε_{t-q}²</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>where:</p><ul><li>r_t: return</li><li>μ_t: conditional mean (constant or other model like ARMA)</li><li>σ_t²: conditional variance</li><li>ω, α_i: model parameters (constraint conditions: ω &gt; 0, α_i ≥ 0)</li></ul></li><li><p><strong>Characteristics of ARCH Model</strong></p><ul><li>Captures volatility clustering phenomenon</li><li>Unconditional variance is constant but conditional variance changes over time</li><li>Stationarity condition: ∑α_i &lt; 1</li><li>Can generate fat-tailed distributions</li></ul></li><li><p><strong>Limitations</strong></p><ul><li>High-order ARCH needed to model long persistent volatility</li><li>Difficult to estimate due to non-negativity constraints</li><li>Cannot capture asymmetric response to volatility shocks</li></ul></li></ul></div><h3 id="garch-generalized-arch-model" tabindex="-1">GARCH (Generalized ARCH) Model <a class="header-anchor" href="#garch-generalized-arch-model" aria-label="Permalink to &quot;GARCH (Generalized ARCH) Model&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">GARCH Model</p><ul><li><p><strong>Concept of GARCH Model</strong> Generalized form of ARCH where conditional variance depends on not only past squared error terms but also past conditional variance. Proposed by Tim Bollerslev in 1986.</p></li><li><p><strong>GARCH(p,q) Model Definition</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>r_t = μ_t + ε_t</span></span>
<span class="line"><span>ε_t = σ_t z_t, z_t ~ N(0,1)</span></span>
<span class="line"><span>σ_t² = ω + ∑(α_i ε_{t-i}²) + ∑(β_j σ_{t-j}²)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>where:</p><ul><li>p: number of lags for GARCH term</li><li>q: number of lags for ARCH term</li><li>ω, α_i, β_j: model parameters (constraint conditions: ω &gt; 0, α_i ≥ 0, β_j ≥ 0)</li></ul></li><li><p><strong>Advantages of GARCH Model</strong></p><ul><li>Can model long persistent volatility with small number of parameters</li><li>GARCH(1,1) alone captures volatility characteristics of most financial time series</li><li>Closed-form expression of unconditional variance possible:<div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Var(ε_t) = ω / (1 - ∑α_i - ∑β_j)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ul></li><li><p><strong>Stationarity and Positive Definiteness Conditions</strong></p><ul><li>Finiteness of unconditional variance: ∑α_i + ∑β_j &lt; 1</li><li>Non-negativity condition for variance: ω &gt; 0, α_i ≥ 0, β_j ≥ 0</li></ul></li><li><p><strong>Persistence and Shock Half-life</strong></p><ul><li>Persistence parameter: η = ∑α_i + ∑β_j</li><li>Volatility shock half-life: log(0.5) / log(η)</li><li>The closer η is to 1, the higher the persistence of shocks</li></ul></li><li><p><strong>Limitations</strong></p><ul><li>Symmetric model: treats positive/negative shocks identically</li><li>Limited handling of tail events</li></ul></li></ul></div><h3 id="asymmetric-garch-models" tabindex="-1">Asymmetric GARCH Models <a class="header-anchor" href="#asymmetric-garch-models" aria-label="Permalink to &quot;Asymmetric GARCH Models&quot;">​</a></h3><p>In financial markets, the <code>leverage effect</code> is observed where negative shocks (price declines) have a greater impact on volatility than positive shocks (price increases). Asymmetric GARCH models have been developed to capture this.</p><div class="danger custom-block"><p class="custom-block-title">Asymmetric Volatility Models</p><ul><li><p><strong>EGARCH (Exponential GARCH)</strong> Models the logarithm of conditional variance, proposed by Nelson (1991):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>log(σ_t²) = ω + ∑β_j log(σ_{t-j}²) + ∑α_i|z_{t-i}| + ∑γ_k z_{t-k}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>If γ &lt; 0, &#39;leverage effect&#39; exists</li><li>Non-negativity constraint on variance automatically satisfied due to log form</li><li>Direct measurement of asymmetric effect possible</li></ul></li><li><p><strong>GJR-GARCH (Glosten-Jagannathan-Runkle GARCH)</strong> Introduces additional term for negative shocks:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>σ_t² = ω + ∑α_i ε_{t-i}² + ∑γ_k ε_{t-k}² I_{t-k} + ∑β_j σ_{t-j}²</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where I_{t-k} is an indicator function that is 1 when ε_{t-k} &lt; 0, otherwise 0</p><ul><li>If γ &gt; 0, &#39;leverage effect&#39; exists</li><li>Intuitive interpretation and easy implementation</li><li>One of the widely used asymmetric models</li></ul></li><li><p><strong>TGARCH (Threshold GARCH)</strong> Similar to GJR-GARCH but directly models standard deviation:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>σ_t = ω + ∑α_i |ε_{t-i}| + ∑γ_k |ε_{t-k}| I_{t-k} + ∑β_j σ_{t-j}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>Absolute value-based model, less sensitive to extreme shocks</li></ul></li><li><p><strong>APARCH (Asymmetric Power ARCH)</strong> Generalized form that models power of volatility:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>σ_t^δ = ω + ∑α_i(|ε_{t-i}| - γ_i ε_{t-i})^δ + ∑β_j σ_{t-j}^δ</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>δ is power parameter (typically 1 or 2)</li><li>Generalized form of many asymmetric GARCH models</li></ul></li></ul></div><h3 id="multivariate-garch-models" tabindex="-1">Multivariate GARCH Models <a class="header-anchor" href="#multivariate-garch-models" aria-label="Permalink to &quot;Multivariate GARCH Models&quot;">​</a></h3><p>Multivariate GARCH models to capture volatility spillover between assets and correlation dynamics are important for portfolio optimization and risk management.</p><div class="tip custom-block"><p class="custom-block-title">Multivariate Volatility Models</p><ul><li><p><strong>VEC-GARCH (Vector GARCH)</strong> Directly models all elements of conditional variance-covariance matrix:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vech(H_t) = c + ∑A_i vech(ε_{t-i}ε&#39;_{t-i}) + ∑B_j vech(H_{t-j})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where vech is an operator that vectorizes the lower triangular part of a matrix</p><ul><li>Very flexible model but has many parameters</li><li>Difficult to apply positive definiteness constraints</li></ul></li><li><p><strong>BEKK-GARCH</strong> Parameterization that ensures positive definiteness of variance-covariance matrix:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>H_t = C&#39;C + ∑A&#39;_i ε_{t-i}ε&#39;_{t-i} A_i + ∑B&#39;_j H_{t-j} B_j</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>Ensures positive definiteness of conditional variance-covariance matrix</li><li>Can capture volatility spillover between assets</li><li>Still has many parameters</li></ul></li><li><p><strong>CCC-GARCH (Constant Conditional Correlation)</strong> Assumes conditional correlation is constant:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>H_t = D_t R D_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where D_t is diagonal matrix of conditional standard deviations, R is constant correlation matrix</p><ul><li>Volatility of each asset is modeled with univariate GARCH</li><li>Significant reduction in number of parameters</li><li>Simple but cannot capture correlation dynamics</li></ul></li><li><p><strong>DCC-GARCH (Dynamic Conditional Correlation)</strong> Extension of CCC that models time-varying correlations:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>H_t = D_t R_t D_t</span></span>
<span class="line"><span>Q_t = (1-a-b)Q̄ + a(u_{t-1}u&#39;_{t-1}) + bQ_{t-1}</span></span>
<span class="line"><span>R_t = diag(Q_t)^(-1/2) Q_t diag(Q_t)^(-1/2)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>where u_t = D_t^(-1)ε_t is standardized residual, Q̄ is unconditional covariance of u_t</p><ul><li>Captures changes in correlation over time</li><li>Good balance between computational efficiency and flexibility</li><li>Widely used in various financial applications</li></ul></li></ul></div><h3 id="estimation-and-diagnostics-of-volatility-models" tabindex="-1">Estimation and Diagnostics of Volatility Models <a class="header-anchor" href="#estimation-and-diagnostics-of-volatility-models" aria-label="Permalink to &quot;Estimation and Diagnostics of Volatility Models&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Volatility Model Implementation</p><ul><li><p><strong>Estimation Methods</strong></p><ul><li><p>Maximum Likelihood Estimation</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L(θ) = ∏(1/σ_t) ϕ(ε_t/σ_t)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where ϕ is the probability density function of standard normal distribution, θ is parameter vector</p></li><li><p>Quasi-MLE: Method that relaxes normality assumption</p></li><li><p>Bayesian MCMC (Markov Chain Monte Carlo) method</p></li><li><p>GMM (Generalized Method of Moments)</p></li></ul></li><li><p><strong>Distributional Assumptions</strong></p><ul><li>Standard Normal Distribution: Most basic assumption</li><li>Student&#39;s t-distribution: Suitable for capturing fat tails</li><li>GED (Generalized Error Distribution): Can adjust skewness and kurtosis</li><li>Asymmetric t-distribution: Simultaneously captures asymmetry and fat tails</li></ul></li><li><p><strong>Model Selection Criteria</strong></p><ul><li>Information criteria: AIC, BIC, HQIC</li><li>Likelihood Ratio Test</li><li>Residual diagnostics: Autocorrelation and heteroskedasticity tests of standardized residuals</li><li>Forecast performance: Evaluation based on realized volatility</li></ul></li><li><p><strong>Volatility Forecasting</strong></p><ul><li>h-step ahead forecasting</li><li>Multi-period volatility</li><li>Forecast accuracy evaluation: MSE, MAE, QLIKE, etc.</li></ul></li></ul></div><p>Volatility models are importantly utilized in various financial applications such as risk management, Value at Risk (VaR) calculation, option pricing, and optimal portfolio construction. In the next section, we will explore nonlinear time series models and machine learning-based approaches.</p><h2 id="_5️⃣-nonlinear-time-series-models-and-regime-switching-models" tabindex="-1">5️⃣ Nonlinear Time Series Models and Regime Switching Models <a class="header-anchor" href="#_5️⃣-nonlinear-time-series-models-and-regime-switching-models" aria-label="Permalink to &quot;5️⃣ Nonlinear Time Series Models and Regime Switching Models&quot;">​</a></h2><p>Financial markets often exhibit nonlinear dynamics transitioning between different <code>regimes</code> or <code>states</code> such as economic expansion, recession, and crisis situations. Various models have been developed to capture this nonlinearity and structural change.</p><h3 id="markov-switching-models" tabindex="-1">Markov Switching Models <a class="header-anchor" href="#markov-switching-models" aria-label="Permalink to &quot;Markov Switching Models&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Markov Switching Models</p><ul><li><p><strong>Basic Concept</strong> A model that assumes time series parameters depend on an unobserved state variable, and this state variable follows a Markov chain.</p></li><li><p><strong>Markov Chain</strong> A stochastic process where the next state depends only on the current state:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P(s_t = j | s_{t-1} = i, s_{t-2}, ...) = P(s_t = j | s_{t-1} = i) = p_{ij}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where p_{ij} is the transition probability from state i to state j</p></li><li><p><strong>Markov Switching AR Model (MS-AR)</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>y_t = μ(s_t) + φ₁(s_t)(y_{t-1} - μ(s_{t-1})) + ... + φ_p(s_t)(y_{t-p} - μ(s_{t-p})) + σ(s_t)ε_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where μ, φ, σ are all parameters that depend on current state s_t</p></li><li><p><strong>Application Examples</strong></p><ul><li>Identifying bull/bear phases in stock market</li><li>Modeling volatility regimes (low/high volatility)</li><li>Identifying business cycles (expansion/recession)</li><li>Analyzing monetary policy regime changes</li></ul></li><li><p><strong>Model Characteristics</strong></p><ul><li>Captures endogenous structural changes</li><li>Allows different dynamics such as conditional mean, autoregressive characteristics, volatility for each state</li><li>Provides estimation of state probabilities and transition probabilities</li><li>Can calculate filtered probability and smoothed probability</li></ul></li></ul></div><h3 id="threshold-autoregressive-tar-model" tabindex="-1">Threshold Autoregressive (TAR) Model <a class="header-anchor" href="#threshold-autoregressive-tar-model" aria-label="Permalink to &quot;Threshold Autoregressive (TAR) Model&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Threshold Models</p><ul><li><p><strong>Concept of TAR Model</strong> A model where time series dynamics differ based on a specific threshold:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>y_t = {</span></span>
<span class="line"><span>  α₁ + φ₁₁y_{t-1} + ... + φ₁ₚy_{t-p} + ε₁ₜ, if z_t ≤ r</span></span>
<span class="line"><span>  α₂ + φ₂₁y_{t-1} + ... + φ₂ₚy_{t-p} + ε₂ₜ, if z_t &gt; r</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>where z_t is threshold variable, r is threshold value</p></li><li><p><strong>SETAR (Self-Exciting TAR) Model</strong> Special case where threshold variable is a past value of the time series itself:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>y_t = {</span></span>
<span class="line"><span>  α₁ + φ₁₁y_{t-1} + ... + φ₁ₚy_{t-p} + ε₁ₜ, if y_{t-d} ≤ r</span></span>
<span class="line"><span>  α₂ + φ₂₁y_{t-1} + ... + φ₂ₚy_{t-p} + ε₂ₜ, if y_{t-d} &gt; r</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>where d is the delay parameter</p></li><li><p><strong>STAR (Smooth Transition AR) Model</strong> Model that allows continuous transition instead of abrupt transition between regimes:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>y_t = (1-G(z_t;γ,r))(α₁ + φ₁&#39;X_t) + G(z_t;γ,r)(α₂ + φ₂&#39;X_t) + ε_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where G is transition function (logistic or exponential), γ is transition speed</p></li><li><p><strong>Financial Applications</strong></p><ul><li>Capturing asymmetric mean reversion in asset returns</li><li>Modeling nonlinear dynamics of volatility</li><li>Analyzing arbitrage inactive zones due to transaction costs</li><li>Analyzing changes in investment behavior according to business cycles</li></ul></li></ul></div><h3 id="nonlinear-extended-models" tabindex="-1">Nonlinear Extended Models <a class="header-anchor" href="#nonlinear-extended-models" aria-label="Permalink to &quot;Nonlinear Extended Models&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Additional Nonlinear Models</p><ul><li><p><strong>ARCH-M (ARCH-in-Mean) Model</strong> Reflects the idea that asset returns depend on risk (conditional variance):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>r_t = μ + λσ_t² + ε_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where λ is risk premium parameter</p></li><li><p><strong>Regime-Switching GARCH Model</strong> Combination of Markov switching model and GARCH:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>r_t = μ(s_t) + ε_t</span></span>
<span class="line"><span>ε_t = σ_t z_t</span></span>
<span class="line"><span>σ_t² = ω(s_t) + α(s_t)ε_{t-1}² + β(s_t)σ_{t-1}²</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>where s_t is Markov state variable</p></li><li><p><strong>Realized Volatility Model</strong> Volatility measurement using high-frequency data:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RV_t = ∑r_{t,i}²</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where r_{t,i} is the i-th high-frequency return on day t</p><ul><li>Time series modeling of realized volatility (HAR-RV, ARFIMA, etc.)</li><li>Based on non-parametric volatility estimation</li></ul></li><li><p><strong>Stochastic Volatility (SV) Model</strong> Assumes volatility itself follows a stochastic process:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>r_t = σ_t z_t</span></span>
<span class="line"><span>log(σ_t²) = α + βlog(σ_{t-1}²) + η_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>where η_t is error term in volatility equation</p><ul><li>Unlike GARCH, allows separate shocks to volatility</li><li>Mainly estimated with Bayesian methodology</li></ul></li></ul></div><h3 id="non-parametric-approaches" tabindex="-1">Non-parametric Approaches <a class="header-anchor" href="#non-parametric-approaches" aria-label="Permalink to &quot;Non-parametric Approaches&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Non-parametric Time Series Methodology</p><ul><li><p><strong>Kernel Regression</strong> Function estimation using weighted averages around data:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>m̂(x) = ∑K_h(x-X_i)Y_i / ∑K_h(x-X_i)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where K_h is kernel function, h is bandwidth</p></li><li><p><strong>Local Polynomial Regression</strong> Method of fitting polynomials around each point:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>min_β ∑K_h(x-X_i)(Y_i - β₀ - β₁(X_i-x) - ... - β_p(X_i-x)^p)²</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p><strong>Non-parametric Density Estimation</strong></p><ul><li>Kernel Density Estimation</li><li>k-Nearest Neighbors method</li></ul></li><li><p><strong>Financial Applications</strong></p><ul><li>Identifying complex nonlinear patterns</li><li>Estimating risk-neutral density in option pricing</li><li>Exploring nonlinear mean-variance relationships</li><li>Constructing prediction intervals</li></ul></li></ul></div><p>Nonlinear time series models are important for capturing complex dynamic characteristics of financial markets. They are particularly useful for modeling phenomena difficult to explain with linear models such as structural changes, regime switching, and asymmetric responses. In the next section, we will explore machine learning-based time series analysis methods that are rapidly developing recently.</p><h2 id="_6️⃣-machine-learning-and-deep-learning-based-time-series-analysis" tabindex="-1">6️⃣ Machine Learning and Deep Learning-Based Time Series Analysis <a class="header-anchor" href="#_6️⃣-machine-learning-and-deep-learning-based-time-series-analysis" aria-label="Permalink to &quot;6️⃣ Machine Learning and Deep Learning-Based Time Series Analysis&quot;">​</a></h2><p>To overcome limitations of traditional statistical models, machine learning and deep learning methodologies are being actively utilized in financial time series analysis recently. These methods have strengths in <code>capturing complex nonlinear patterns</code>, <code>processing large-scale data</code>, and <code>integrating multi-source information</code>.</p><h3 id="decision-tree-based-methodologies" tabindex="-1">Decision Tree-Based Methodologies <a class="header-anchor" href="#decision-tree-based-methodologies" aria-label="Permalink to &quot;Decision Tree-Based Methodologies&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Tree-Based Ensemble Methods</p><ul><li><p><strong>Random Forest</strong> Ensemble method based on multiple decision trees:</p><ul><li>Each tree is trained on bootstrap sample of data</li><li>Ensures diversity through feature randomization</li><li>Time series features: lag variables, moving averages, volatility measures, etc. used as features</li></ul></li><li><p><strong>Gradient Boosting</strong> Ensemble method that sequentially corrects errors of previous models:</p><ul><li>Efficient implementations like XGBoost, LightGBM, CatBoost</li><li>Corrects model in gradient direction of loss function</li><li>Can identify variable influence through feature importance measurement</li></ul></li><li><p><strong>Financial Applications</strong></p><ul><li>Return direction prediction (directional classification)</li><li>Volatility forecasting</li><li>Anomaly detection (market anomalies)</li><li>Identifying market drivers through variable importance</li></ul></li></ul></div><h3 id="support-vector-machines-and-kernel-methods" tabindex="-1">Support Vector Machines and Kernel Methods <a class="header-anchor" href="#support-vector-machines-and-kernel-methods" aria-label="Permalink to &quot;Support Vector Machines and Kernel Methods&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">SVM and Kernel Techniques</p><ul><li><p><strong>Support Vector Regression (SVR)</strong> Models nonlinear relationships with margin-based approach:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>min 1/2||w||² + C∑ξ_i</span></span>
<span class="line"><span>subject to |y_i - f(x_i)| ≤ ε + ξ_i, ξ_i ≥ 0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li>Allows some errors with ε-insensitive zone</li><li>Nonlinear mapping through kernel trick</li><li>Tends to have good generalization performance</li></ul></li><li><p><strong>Main Kernel Functions</strong></p><ul><li>Linear kernel: K(x,y) = x^T y</li><li>Polynomial kernel: K(x,y) = (γx^T y + r)^d</li><li>RBF kernel: K(x,y) = exp(-γ||x-y||²)</li><li>Sigmoid kernel: K(x,y) = tanh(γx^T y + r)</li></ul></li><li><p><strong>Financial Applications</strong></p><ul><li>Price and volatility forecasting</li><li>Stock trend classification</li><li>Nonlinear mean reversion modeling</li><li>Market regime classification</li></ul></li></ul></div><h3 id="deep-neural-network-models" tabindex="-1">Deep Neural Network Models <a class="header-anchor" href="#deep-neural-network-models" aria-label="Permalink to &quot;Deep Neural Network Models&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Deep Learning-Based Time Series Analysis</p><ul><li><p><strong>Recurrent Neural Networks (RNN)</strong> Neural networks with feedback connections to capture temporal dependencies:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>h_t = σ_h(W_h h_{t-1} + W_x x_t + b_h)</span></span>
<span class="line"><span>y_t = σ_y(W_y h_t + b_y)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>where h_t is hidden state, x_t is input, y_t is output</p></li><li><p><strong>LSTM (Long Short-Term Memory)</strong> Special RNN structure for learning long-term dependencies:</p><ul><li>Gate mechanisms: input gate, forget gate, output gate</li><li>Maintains long-term information through cell state</li><li>Mitigates gradient vanishing problem</li></ul></li><li><p><strong>GRU (Gated Recurrent Unit)</strong> Simplified structure of LSTM:</p><ul><li>Reset gate and update gate</li><li>Fewer parameters than LSTM and computationally efficient</li><li>Performance often similar to LSTM</li></ul></li><li><p><strong>Temporal Convolutional Networks (TCN)</strong> Convolutional neural networks specialized for time series data:</p><ul><li>Processes long sequences with dilated convolution</li><li>Prevents future information leakage with causal convolution</li><li>Often more efficient to train than RNN due to parallel processing capability</li></ul></li><li><p><strong>Attention Mechanism and Transformer</strong> Weight-based context generation mechanism:</p><ul><li>Captures relationships within time series through self-attention</li><li>Direct connection between all positions in sequence</li><li>Selective focus on relevant parts of input sequence</li><li>No sequential processing constraint of RNN</li></ul></li><li><p><strong>Hybrid Models</strong></p><ul><li>LSTM-GARCH: Combines LSTM and GARCH for volatility modeling</li><li>CNN-LSTM: Uses CNN for feature extraction, LSTM for temporal dependencies</li><li>Encoder-Decoder structure: Sequence-to-sequence model for time series forecasting</li></ul></li></ul></div><h3 id="time-series-specific-machine-learning-approaches" tabindex="-1">Time Series-Specific Machine Learning Approaches <a class="header-anchor" href="#time-series-specific-machine-learning-approaches" aria-label="Permalink to &quot;Time Series-Specific Machine Learning Approaches&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Time Series-Specific ML Methods</p><ul><li><p><strong>DeepAR</strong> Probabilistic forecasting model developed by Amazon:</p><ul><li>RNN-based autoregressive model</li><li>Predicts probability distribution not point forecast</li><li>Can learn common patterns in multivariate time series</li></ul></li><li><p><strong>N-BEATS</strong> Deep neural network-based interpretable time series forecasting model:</p><ul><li>Residual connections and hierarchical structure</li><li>Explicit decomposition of trend and seasonality</li><li>Combines black-box prediction and interpretability</li></ul></li><li><p><strong>Prophet</strong> Decomposition-based forecasting framework developed by Facebook:</p><ul><li>Additive model of trend, seasonality, and holiday effects</li><li>Robust to missing data and outliers</li><li>Focus on business time series</li></ul></li><li><p><strong>Neural ODE (Ordinary Differential Equations)</strong> Deep learning method that models continuous-time dynamics:</p><ul><li>Models time series dynamics in differential equation form</li><li>Suitable for handling observations at irregular time intervals</li><li>Modern approach to state space models</li></ul></li></ul></div><h3 id="evaluation-and-interpretation-of-machine-learning-models" tabindex="-1">Evaluation and Interpretation of Machine Learning Models <a class="header-anchor" href="#evaluation-and-interpretation-of-machine-learning-models" aria-label="Permalink to &quot;Evaluation and Interpretation of Machine Learning Models&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">ML Model Evaluation and Interpretation Methods</p><ul><li><p><strong>Time Series Cross-Validation</strong></p><ul><li>Simple split: Train on past data, validate on future data</li><li>Expanding window: Gradually expand training set while moving validation period</li><li>Rolling window: Move training and validation with fixed-size window</li></ul></li><li><p><strong>Performance Metrics</strong></p><ul><li>MSE (Mean Squared Error), RMSE (Root MSE)</li><li>MAE (Mean Absolute Error), MAPE (Mean Absolute Percentage Error)</li><li>Directional Accuracy</li><li>Sharpe Ratio, Information Ratio and other investment performance metrics</li></ul></li><li><p><strong>Feature Importance Analysis</strong></p><ul><li>Permutation Importance</li><li>SHAP (SHapley Additive exPlanations) values</li><li>Partial Dependence Plots</li><li>Individual Conditional Expectation curves</li></ul></li><li><p><strong>Model Interpretation Techniques</strong></p><ul><li>LIME (Local Interpretable Model-agnostic Explanations)</li><li>Attention weight visualization</li><li>Prototype-based interpretation</li><li>Rule extraction</li></ul></li></ul></div><p>Machine learning and deep learning methodologies are opening new possibilities in financial time series analysis, but there are also several challenges such as model complexity, overfitting risk, and interpretability issues. It is important to use these advanced technologies complementarily with traditional statistical methodologies. In the next section, we will explore application cases of time series analysis in financial engineering.</p><h2 id="_7️⃣-financial-engineering-applications-of-time-series-analysis" tabindex="-1">7️⃣ Financial Engineering Applications of Time Series Analysis <a class="header-anchor" href="#_7️⃣-financial-engineering-applications-of-time-series-analysis" aria-label="Permalink to &quot;7️⃣ Financial Engineering Applications of Time Series Analysis&quot;">​</a></h2><p>Time series analysis methodologies are importantly utilized in various areas of financial engineering. This section will explore major application areas such as risk management, asset price forecasting, and portfolio optimization.</p><h3 id="time-series-analysis-in-risk-management" tabindex="-1">Time Series Analysis in Risk Management <a class="header-anchor" href="#time-series-analysis-in-risk-management" aria-label="Permalink to &quot;Time Series Analysis in Risk Management&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Risk Measurement and Management</p><ul><li><p><strong>Value at Risk (VaR) Calculation</strong> Estimating maximum expected loss at a specific confidence level:</p><ul><li>Historical simulation: Percentile of past return distribution</li><li>Parametric method: Conditional variance estimation through GARCH, etc.</li><li>Monte Carlo simulation: Scenario generation based on parameter estimates</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VaR_α = μ_t + σ_t × Φ^(-1)(α)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where Φ^(-1) is the inverse cumulative distribution function of normal distribution</p></li><li><p><strong>Expected Shortfall (ES, Conditional VaR)</strong> Expected value of losses exceeding VaR:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ES_α = E[r_t | r_t &lt; VaR_α]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>More sensitive to extreme risk than VaR</li><li>Satisfies mathematical properties of coherent risk measure compared to VaR</li></ul></li><li><p><strong>Stress Testing and Scenario Analysis</strong></p><ul><li>Historical scenarios: Apply return patterns from past crisis events</li><li>Hypothetical scenarios: Generate stress scenarios based on time series models</li><li>Reverse stress testing: Backtrack scenarios that cause specific loss levels</li></ul></li><li><p><strong>Risk Factor Decomposition</strong></p><ul><li>Identify return structure through Principal Component Analysis (PCA)</li><li>Decompose systematic/unsystematic risk through factor models</li><li>Analyze risk spillover patterns through multivariate GARCH</li></ul></li></ul></div><h3 id="asset-price-forecasting-and-investment-strategies" tabindex="-1">Asset Price Forecasting and Investment Strategies <a class="header-anchor" href="#asset-price-forecasting-and-investment-strategies" aria-label="Permalink to &quot;Asset Price Forecasting and Investment Strategies&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Price Forecasting and Investment Decision-Making</p><ul><li><p><strong>Time Series-Based Forecasting Models</strong></p><ul><li>Traditional models like ARIMA, GARCH</li><li>Machine learning/deep learning-based forecasting models</li><li>Models integrating technical indicators (moving averages, RSI, MACD, etc.)</li><li>Models combining fundamental data and market sentiment indicators</li></ul></li><li><p><strong>Algorithmic Trading Strategies</strong></p><ul><li>Mean reversion strategy: Utilizes tendency for prices to revert to long-term average</li><li>Momentum strategy: Utilizes persistence of price trends</li><li>Statistical arbitrage: Pair trading based on cointegration relationships</li><li>Machine learning-based signal generation</li></ul></li><li><p><strong>Investment Performance Evaluation</strong></p><ul><li>Sharpe Ratio: Measures risk-adjusted return<div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SR = (R_p - R_f) / σ_p</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li>Information Ratio: Excess performance relative to benchmark</li><li>Maximum Drawdown: Decline from peak to trough</li><li>Alpha and Beta: Excess return and sensitivity relative to market</li></ul></li></ul></div><h3 id="derivative-pricing-and-hedging" tabindex="-1">Derivative Pricing and Hedging <a class="header-anchor" href="#derivative-pricing-and-hedging" aria-label="Permalink to &quot;Derivative Pricing and Hedging&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Derivatives and Time Series Analysis</p><ul><li><p><strong>Option Pricing Models</strong></p><ul><li>Estimate volatility parameter in Black-Scholes-Merton model</li><li>GARCH option pricing: Reflects time-varying volatility</li><li>Stochastic Volatility models</li><li>Jump Diffusion models: Capture extreme price movements</li></ul></li><li><p><strong>Implied Volatility Surface Modeling</strong></p><ul><li>Analyze dynamics of implied volatility surface over time</li><li>Identify major movements of volatility surface through Principal Component Analysis (PCA)</li><li>Calculate Greeks for volatility risk management</li></ul></li><li><p><strong>Dynamic Hedging Strategies</strong></p><ul><li>Delta-gamma hedging: Manage sensitivity to underlying asset price changes</li><li>Vega hedging: Manage exposure to volatility changes</li><li>Derive optimal hedge ratio based on time series models<div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>h* = ρ_s,f × (σ_s / σ_f)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>where ρ is correlation coefficient between spot and futures, σ is respective standard deviation</li></ul></li><li><p><strong>Risk-Neutral Probability Density Estimation</strong></p><ul><li>Extract market&#39;s expected probability distribution from option prices</li><li>Non-parametric methods: Kernel smoothing, spline interpolation</li><li>Parametric methods: Mixture normal distributions, generalized beta distribution, etc.</li></ul></li></ul></div><h3 id="portfolio-optimization-and-asset-allocation" tabindex="-1">Portfolio Optimization and Asset Allocation <a class="header-anchor" href="#portfolio-optimization-and-asset-allocation" aria-label="Permalink to &quot;Portfolio Optimization and Asset Allocation&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Time Series-Based Portfolio Management</p><ul><li><p><strong>Dynamic Asset Allocation</strong></p><ul><li>Estimate time-varying covariance matrix (DCC-GARCH, etc.)</li><li>Optimal allocation by market phase through regime switching models</li><li>Conditional Sharpe ratio maximization strategy</li></ul></li><li><p><strong>Risk Parity</strong> Allocate so each asset contributes equally to portfolio risk:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>w_i ∝ 1 / (σ_i × ρ_i,p)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>where ρ_i,p is correlation coefficient between asset i and portfolio</p></li><li><p><strong>Black-Litterman Model</strong> Integrates investor&#39;s subjective views into market equilibrium prices:</p><ul><li>CAPM-based equilibrium expected returns</li><li>Expected return views derived from time series models</li><li>Integration of two information sources through Bayesian methodology</li></ul></li><li><p><strong>Time Series Property-Based Factor Investing</strong></p><ul><li>Momentum factor: Persistence of past returns</li><li>Low volatility factor: Risk-return anomaly</li><li>Mean reversion factor: Price reversion phenomenon</li><li>Seasonality factors: Monthly, day-of-week effects, etc.</li></ul></li></ul></div><h3 id="economic-and-financial-policy-analysis" tabindex="-1">Economic and Financial Policy Analysis <a class="header-anchor" href="#economic-and-financial-policy-analysis" aria-label="Permalink to &quot;Economic and Financial Policy Analysis&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Macroeconomic and Policy Impact Analysis</p><ul><li><p><strong>Monetary Policy Impact Analysis</strong></p><ul><li>Analyze spillover effects of interest rate changes on financial markets through VAR/VECM</li><li>TVP-VAR (Time-Varying Parameter VAR): Capture changes in policy effects over time</li><li>FAVAR (Factor-Augmented VAR): Integrate information from large-scale datasets</li></ul></li><li><p><strong>Event Study</strong> Analyze market impact of events such as policy announcements, economic indicator releases:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AR_t = R_t - E[R_t]</span></span>
<span class="line"><span>CAR = ∑AR_t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>where AR is Abnormal Return, CAR is Cumulative Abnormal Return</p></li><li><p><strong>Structural Change Detection</strong></p><ul><li>Chow test: Verify known structural change point</li><li>CUSUM test: Sequential monitoring of parameter stability</li><li>Bai-Perron test: Identify multiple structural change points</li></ul></li><li><p><strong>Financial Instability Index Development</strong></p><ul><li>Integrate various market indicators time series</li><li>Construct financial stress index through Principal Component Analysis</li><li>Estimate financial crisis probability through regime switching models</li></ul></li></ul></div><p>Applications of time series analysis methodologies in financial engineering are very extensive, and these techniques are utilized for various purposes such as risk management, profit generation, and system stability monitoring in financial markets. In the next section, we will explore recent trends and future directions in financial time series analysis.</p><h2 id="_8️⃣-recent-trends-and-future-directions-in-financial-time-series-analysis" tabindex="-1">8️⃣ Recent Trends and Future Directions in Financial Time Series Analysis <a class="header-anchor" href="#_8️⃣-recent-trends-and-future-directions-in-financial-time-series-analysis" aria-label="Permalink to &quot;8️⃣ Recent Trends and Future Directions in Financial Time Series Analysis&quot;">​</a></h2><p>The field of financial time series analysis is rapidly developing and continues to evolve due to emergence of new data sources, improvements in computing power, methodological innovations, etc. This section explores current major trends and future development directions.</p><h3 id="utilization-of-big-data-and-alternative-data" tabindex="-1">Utilization of Big Data and Alternative Data <a class="header-anchor" href="#utilization-of-big-data-and-alternative-data" aria-label="Permalink to &quot;Utilization of Big Data and Alternative Data&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">New Data Sources</p><ul><li><p><strong>Alternative Data</strong></p><ul><li><strong>Social Media Data</strong>: Sentiment analysis from Twitter, Reddit, etc.</li><li><strong>Satellite Images</strong>: Economic activity indicators like retail parking lot occupancy, crop production</li><li><strong>Mobile Location Data</strong>: Retail store visit traffic, logistics movement patterns</li><li><strong>Web Scraping Data</strong>: Online prices, product reviews, job postings, etc.</li><li><strong>Credit Card and POS Data</strong>: Real-time consumer spending patterns</li><li><strong>IoT Sensor Data</strong>: Industrial activity, energy consumption, traffic flow, etc.</li></ul></li><li><p><strong>High-Frequency Data</strong></p><ul><li>Tick Data: Individual trade or quote level data</li><li>Order Book Data: Market microstructure analysis</li><li>Special time series methodologies for ultra-high frequency data processing</li></ul></li><li><p><strong>Text Data and NLP</strong></p><ul><li>Text analysis of central bank minutes, corporate earnings reports, news articles, etc.</li><li>Word Embedding and topic modeling</li><li>Construct market sentiment indicators through sentiment analysis</li><li>Combined models of text features and numerical time series</li></ul></li></ul></div><h3 id="development-of-deep-learning-and-artificial-intelligence" tabindex="-1">Development of Deep Learning and Artificial Intelligence <a class="header-anchor" href="#development-of-deep-learning-and-artificial-intelligence" aria-label="Permalink to &quot;Development of Deep Learning and Artificial Intelligence&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Advanced AI Technology</p><ul><li><p><strong>Deep Learning Architecture Development</strong></p><ul><li>Attention mechanism and Transformer: Enhanced long-term dependency capture</li><li>Graph Neural Networks (GNN): Financial network analysis</li><li>Memory-Augmented Neural Networks: Improved long-term memory capability</li><li>Mixture Density Networks (MDN): Multi-modal distribution prediction</li></ul></li><li><p><strong>Financial Applications of Reinforcement Learning</strong></p><ul><li>Dynamic portfolio optimization</li><li>Real-time trading strategy development</li><li>Optimal Execution strategies</li><li>Market simulation and agent-based modeling</li></ul></li><li><p><strong>Explainable AI (XAI) Development</strong></p><ul><li>Improved interpretation techniques for black-box models</li><li>Enhanced model transparency for regulatory compliance</li><li>Neural network pruning and knowledge distillation</li><li>Neuro-symbolic approaches</li></ul></li><li><p><strong>Transfer Learning and Meta-Learning</strong></p><ul><li>Knowledge transfer across various financial time series</li><li>Modeling new asset classes with limited data</li><li>Integrated learning of multi-market/asset patterns</li></ul></li></ul></div><h3 id="causal-inference-and-structural-modeling" tabindex="-1">Causal Inference and Structural Modeling <a class="header-anchor" href="#causal-inference-and-structural-modeling" aria-label="Permalink to &quot;Causal Inference and Structural Modeling&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Causality and Structural Relationships</p><ul><li><p><strong>Causal Inference Methodology</strong></p><ul><li>Extensions of Granger Causality</li><li>Causal graph learning based on conditional independence tests</li><li>Instrumental Variables approach</li><li>Utilizing Natural Experiments</li></ul></li><li><p><strong>Structural Time Series Models</strong></p><ul><li>Structural VAR: Imposing constraints based on economic theory</li><li>Bayesian structural time series models</li><li>Dynamic Causal Modeling</li><li>Neuro-structural models: Combination of neural networks and structural models</li></ul></li><li><p><strong>Counterfactual Analysis</strong></p><ul><li>&quot;What if&quot; scenario analysis</li><li>Evaluate effects of policy interventions</li><li>Construct stress test scenarios</li><li>Counterfactual evaluation of algorithmic trading strategies</li></ul></li></ul></div><h3 id="development-of-computational-methodologies-and-systems" tabindex="-1">Development of Computational Methodologies and Systems <a class="header-anchor" href="#development-of-computational-methodologies-and-systems" aria-label="Permalink to &quot;Development of Computational Methodologies and Systems&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Advanced Computational Techniques</p><ul><li><p><strong>Bayesian Methodology Development</strong></p><ul><li>Improved efficiency of MCMC (Markov Chain Monte Carlo)</li><li>Variational Inference techniques</li><li>Bayesian Deep Learning</li><li>Improved uncertainty quantification and prediction intervals</li></ul></li><li><p><strong>Distributed and Parallel Computing</strong></p><ul><li>Large-scale time series model training using GPU/TPU</li><li>Real-time data processing through distributed systems</li><li>Low-latency analysis through edge computing</li><li>Cloud-based time series analysis pipelines</li></ul></li><li><p><strong>Online Learning and Stream Processing</strong></p><ul><li>Incremental model update techniques</li><li>Concept drift detection and adaptation</li><li>Efficient algorithms for streaming data</li><li>Real-time anomaly detection systems</li></ul></li><li><p><strong>Potential Applications of Quantum Computing</strong></p><ul><li>Portfolio optimization problems</li><li>Large-scale time series pattern recognition</li><li>Option pricing models</li><li>Monte Carlo simulation acceleration</li></ul></li></ul></div><h3 id="future-directions-of-financial-time-series-analysis" tabindex="-1">Future Directions of Financial Time Series Analysis <a class="header-anchor" href="#future-directions-of-financial-time-series-analysis" aria-label="Permalink to &quot;Future Directions of Financial Time Series Analysis&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Future Development Directions</p><ul><li><p><strong>Acceleration of Convergence Research</strong></p><ul><li>Multidisciplinary approaches including finance, statistics, computer science, physics</li><li>Synergy between traditional time series methodologies and machine learning</li><li>Integration of economic theory and data-driven approaches</li><li>Combination of behavioral economics and time series analysis</li></ul></li><li><p><strong>Enhanced Real-time and Adaptability</strong></p><ul><li>Ultra-low latency analysis for microsecond-level decision-making</li><li>Self-adjusting models that adapt to market environment changes</li><li>Continuous learning and model update systems</li><li>Development of Edge Analytics</li></ul></li><li><p><strong>Increased Interpretability and Transparency</strong></p><ul><li>Development of interpretation techniques for complex models</li><li>Model validation framework in regulatory environment</li><li>Improved model risk management methodology</li><li>Enhanced Fairness, Accountability, Transparency (XAI)</li></ul></li><li><p><strong>Integration of Sustainability Factors</strong></p><ul><li>Time series modeling of ESG (Environmental, Social, Governance) factors</li><li>Analyze impact of climate risk on asset prices</li><li>Time series methodologies for sustainable investment strategies</li><li>Integrated modeling of long-term sustainability and short-term market dynamics</li></ul></li></ul></div><p>Financial time series analysis is a dynamic field where theoretical development and practical application constantly interact. Development in big data, artificial intelligence, and computing power is opening new possibilities in this field, while also presenting new challenges such as complexity management, model risk, and interpretability. Through continuous innovation and multidisciplinary approaches, financial time series analysis will continue to play an important role as a core area of financial engineering.</p><h2 id="_9️⃣-conclusion" tabindex="-1">9️⃣ Conclusion <a class="header-anchor" href="#_9️⃣-conclusion" aria-label="Permalink to &quot;9️⃣ Conclusion&quot;">​</a></h2><p><strong>Time series analysis is a core methodology for understanding and modeling temporal characteristics of financial data, providing a foundation for various fields of financial engineering. As the complexity of financial markets increases and the volume and variety of data explode, the importance and scope of application of time series analysis methodologies continue to expand.</strong></p><p>This page explored various time series analysis methodologies from basic characteristics of time series data to traditional statistical models, volatility models, nonlinear models, and state-of-the-art machine learning and deep learning approaches. We also explored how these methodologies are applied to major areas of financial engineering such as risk management, asset price forecasting, portfolio optimization, and derivative pricing.</p><div class="tip custom-block"><p class="custom-block-title">Core Roles of Time Series Analysis</p><ul><li><strong>Pattern Recognition and Forecasting</strong>: Provides foundation for identifying temporal patterns in financial markets and forecasting future movements</li><li><strong>Risk Measurement</strong>: Estimates various risk indicators such as volatility, VaR, extreme event probabilities</li><li><strong>Identifying Structural Relationships</strong>: Analyzes interactions and causal relationships among various financial variables</li><li><strong>Policy and Strategy Evaluation</strong>: Evaluates effects of investment strategies, risk management methods, policy interventions</li><li><strong>System Stability Monitoring</strong>: Tracks stability and vulnerability of financial systems</li></ul></div><p>Financial time series analysis is a field where theory and practice are closely connected. It has a virtuous cycle structure where academic development is directly applied to solving real financial problems, and real-world challenges in turn stimulate theoretical innovation.</p><p>Future financial time series analysis is expected to develop in directions such as integration of more diverse data sources, fusion of artificial intelligence and existing methodologies, enhanced real-time analysis capabilities, and improved interpretability and transparency. These developments will contribute to enhancing the efficiency, stability, and inclusiveness of financial markets.</p><p><strong>For students and professionals studying financial engineering, it is important to develop the ability to effectively utilize principles and methodologies of time series analysis based on a solid statistical foundation along with understanding of state-of-the-art data science techniques. Time series analysis will remain an essential tool of financial engineering in the rapidly evolving financial environment.</strong></p><h2 id="🔟-references-and-recommended-resources" tabindex="-1">🔟 References and Recommended Resources <a class="header-anchor" href="#🔟-references-and-recommended-resources" aria-label="Permalink to &quot;🔟 References and Recommended Resources&quot;">​</a></h2><p>The following resources will be helpful for a deeper understanding of time series analysis and financial engineering:</p><div class="tip custom-block"><p class="custom-block-title">Recommended Books</p><ul><li>&quot;Financial Time Series Analysis&quot; (Ruey S. Tsay, Korean translation)</li><li>&quot;Fundamentals and Applications of Time Series Analysis&quot; (Kim Chung-rak, Lee Jang-taek)</li><li>&quot;Financial Econometrics: Applications of Time Series Analysis&quot; (Kim Myung-jik, Jang Kook-hyun)</li><li>&quot;Time Series Analysis&quot; (James D. Hamilton)</li><li>&quot;Analysis of Financial Time Series&quot; (Ruey S. Tsay)</li><li>&quot;Advances in Financial Machine Learning&quot; (Marcos Lopez de Prado)</li><li>&quot;Financial Time Series Analysis: A Practical Guide to Machine Learning and Deep Learning Models&quot; (Vishwanathan Venkateswaran)</li><li>&quot;Econometrics of Financial Markets&quot; (Campbell, Lo, MacKinlay)</li></ul></div><div class="warning custom-block"><p class="custom-block-title">Online Lectures and Resources</p><ul><li>Coursera: &quot;Practical Time Series Analysis&quot; (State University of New York)</li><li>edX: &quot;Financial Engineering and Risk Management&quot; (Columbia University)</li><li>MIT OpenCourseWare: &quot;Statistical Method in Economics&quot;</li><li>K-MOOC: &quot;Financial Time Series Analysis&quot; (Yonsei University)</li><li>Kaggle: &quot;Time Series Analysis&quot; tutorials</li><li>QuantStart blog: Financial time series analysis tutorials</li><li>PyData conference presentations and videos</li><li>GitHub: Open source financial time series analysis projects</li></ul></div><div class="danger custom-block"><p class="custom-block-title">Major Academic Journals and Conferences</p><ul><li>Journal of Econometrics</li><li>Journal of Financial Econometrics</li><li>Quantitative Finance</li><li>Journal of Empirical Finance</li><li>Journal of Time Series Analysis</li><li>International Journal of Forecasting</li><li>Neural Information Processing Systems (NeurIPS)</li><li>International Conference on Machine Learning (ICML)</li><li>International Conference on Financial Engineering</li><li>Computational and Financial Econometrics (CFE) Conference</li></ul></div><div class="tip custom-block"><p class="custom-block-title">Software and Libraries</p><ul><li><p><strong>Python</strong>:</p><ul><li>pandas, numpy, scipy</li><li>statsmodels (ARIMA, VAR, etc.)</li><li>pmdarima (auto ARIMA)</li><li>arch (GARCH models)</li><li>Prophet (Facebook)</li><li>scikit-learn (ML modeling)</li><li>TensorFlow, PyTorch (deep learning)</li><li>Darts, sktime (time series specialized tools)</li></ul></li><li><p><strong>R</strong>:</p><ul><li>forecast package</li><li>tseries package</li><li>rugarch package</li><li>vars package</li><li>quantmod package</li><li>TTR package</li></ul></li><li><p><strong>Other Tools</strong>:</p><ul><li>MATLAB Econometrics Toolbox</li><li>EViews</li><li>Stata Time Series module</li><li>JMP Time Series platform</li></ul></li></ul></div><div class="info custom-block"><p class="custom-block-title">Notes</p><ul><li>The content on this page is written for educational and informational purposes and cannot replace investment recommendations or financial advice. Please seek professional advice for actual financial decision-making.</li></ul></div>`,117)]))}const h=t(l,[["render",o]]);export{g as __pageData,h as default};
